// Writes src/world/registry.generated.ts from contracts/events/registry.yaml (HR-5, FR-WLD-04).
// Run with `node apps/web/scripts/generate-registry.mjs` (regenerate after registry.yaml changes;
// contracts/ is owned by the architect, builders never edit it, only regenerate this file).
import fs from "node:fs";
import { fileURLToPath } from "node:url";

const at = (p) => fileURLToPath(new URL(p, import.meta.url));
export const REGISTRY_PATH = at("../../../contracts/events/registry.yaml");
export const OUT_PATH = at("../src/world/registry.generated.ts");
const HEADER =
  "AUTO-GENERATED by apps/web/scripts/generate-registry.mjs from contracts/events/registry.yaml; run to refresh.";

/** Every `  <family.verb>:` key nested directly under the top-level `types:` mapping (same shape
 * assumed by registry.test.ts, which reads the ground truth straight from the yaml itself). */
export function registeredTypes() {
  const text = fs.readFileSync(REGISTRY_PATH, "utf-8");
  const lines = text.split("\n");
  const startIndex = lines.findIndex((l) => l.trim() === "types:");
  if (startIndex < 0)
    throw new Error("contracts/events/registry.yaml has no top-level `types:` key");
  const types = [];
  for (const line of lines.slice(startIndex + 1)) {
    const m = line.match(/^ {2}([a-z][a-z_]*\.[a-z_]+):\s*$/);
    if (m?.[1]) types.push(m[1]);
    else if (line.length > 0 && !line.startsWith(" ")) break;
  }
  return types;
}

export function generate() {
  const types = registeredTypes();
  return `// ${HEADER}\nexport const KNOWN_EVENT_TYPES: readonly string[] = ${JSON.stringify(types, null, 2)};\n`;
}

if (process.argv[1]?.endsWith("generate-registry.mjs")) {
  fs.writeFileSync(OUT_PATH, generate());
}
